WITH segment_daily AS ( SELECT cd.cd_gender, cd.cd_education_status, d.d_date, d.d_year, d.d_month_seq, SUM(ss.ss_net_paid) AS daily_net_paid, COUNT(*) AS daily_txn_cnt, CASE WHEN cd.cd_purchase_estimate < 800 THEN 'Low' WHEN cd.cd_purchase_estimate BETWEEN 800 AND 3500 THEN 'Medium' ELSE 'High' END AS purchase_estimate_bucket, COUNT(DISTINCT s.s_state) AS distinct_state_cnt FROM store_sales ss JOIN customer_demographics cd ON ss.ss_cdemo_sk = cd.cd_demo_sk JOIN date_dim d ON ss.ss_sold_date_sk = d.d_date_sk JOIN store s ON ss.ss_store_sk = s.s_store_sk GROUP BY cd.cd_gender, cd.cd_education_status, d.d_date, d.d_year, d.d_month_seq, cd.cd_purchase_estimate ) SELECT cd_gender, cd_education_status, d_year, d_month_seq, SUM(daily_txn_cnt) AS total_txn_cnt, SUM(daily_net_paid) AS total_net_paid, MIN(daily_net_paid) AS min_daily_net, MAX(daily_net_paid) AS max_daily_net, purchase_estimate_bucket FROM segment_daily GROUP BY cd_gender, cd_education_status, d_year, d_month_seq, purchase_estimate_bucket HAVING SUM(daily_txn_cnt) > 20 ORDER BY total_net_paid DESC
